    },
    {
      "维度": "库存周转：300件首单消化周期",
      "计划值": "首单300件，45天内自然销量≥30件（周转>4周期止损）",
      "待回填实际值": "",
      "判定标准": "45天自然销量≥30件通过；<30件触发库存止损"
    }
  ],
